-- Reset demo ANADEM
-- Gerado automaticamente a partir de colaboradores.xlsx
-- As credenciais restauradas devem ser redefinidas apos o restore.

BEGIN;
SET TIME ZONE 'America/Sao_Paulo';

CREATE OR REPLACE FUNCTION pg_temp.demo_uuid(seed text)
RETURNS uuid
LANGUAGE sql
IMMUTABLE
AS $fn$
    SELECT (
        substr(md5(seed), 1, 8) || '-' ||
        substr(md5(seed), 9, 4) || '-' ||
        substr(md5(seed), 13, 4) || '-' ||
        substr(md5(seed), 17, 4) || '-' ||
        substr(md5(seed), 21, 12)
    )::uuid;
$fn$;

