INSERT INTO sectors (
    company_id,
    name,
    slug,
    color,
    description,
    is_active,
    created_at,
    updated_at
)
SELECT
    company.id,
    sector_seed.name,
    sector_seed.slug,
    sector_seed.color,
    sector_seed.description,
    true,
    now(),
    now()
FROM demo_sectors AS sector_seed
