) AS company;

INSERT INTO rooms (
    sector_id,
    name,
    description,
    is_active,
    created_at,
    updated_at
)
SELECT
    sector.id,
    room_seed.room_name,
    room_seed.description,
    true,
    now(),
    now()
FROM sectors AS sector
JOIN (
    VALUES
        ('*', 'Operacao', 'Ambiente principal para a rotina do setor.'),
        ('*', 'Backoffice', 'Espaco de apoio e acompanhamento interno.'),
        ('ti', 'Infraestrutura', 'Espaco para equipamentos, redes e sustentacao tecnica.'),
        ('compras', 'Homologacao', 'Espaco para validacao de fornecedores e aquisicoes.'),
        ('financeiro', 'Tesouraria', 'Espaco para operacoes financeiras e conciliacoes.'),
        ('juridico', 'Contratos', 'Espaco para revisao e guarda de documentos juridicos.'),
        ('ceo-presidencia', 'Diretoria', 'Sala executiva para tratativas de presidencia.')
) AS room_seed(sector_slug, room_name, description)
    ON room_seed.sector_slug = '*' OR room_seed.sector_slug = sector.slug
WHERE sector.deleted_at IS NULL;

WITH ranked_collaborators AS (
    SELECT
        collaborator.*,
        ROW_NUMBER() OVER (ORDER BY collaborator.email) AS sequence_number
    FROM demo_collaborators AS collaborator
)
INSERT INTO users (
    name,
    email,
    email_verified_at,
    password,
    role,
    global_role,
    sector_id,
    room_id,
    must_change_password,
    is_active,
    theme_preference,
    created_at,
    updated_at
)
SELECT
    collaborator.name,
    collaborator.email,
    now() - INTERVAL '15 days' + (collaborator.sequence_number * INTERVAL '8 minutes'),
    '$2y$10$f94Q1.7IMxj0.DqExE75tOCWeO/oGRiJx5qds.hXYqx.TB2Ej0ZsC',
    CASE
        WHEN collaborator.email = 'admin@anadem.com.br' THEN 'super_admin'
        WHEN collaborator.email IN ('alisson.schimitz@aiatecnologia.com.br', 'adriel@anadem.org.br') THEN 'sector_admin'
        WHEN collaborator.email = 'adilio.silva@aiatecnologia.com.br' THEN 'technician'
        ELSE 'requester'
    END,
    CASE
        WHEN collaborator.email = 'admin@anadem.com.br' THEN 'super_admin'
        ELSE 'collaborator'
    END,
    sector.id,
    (
        SELECT room.id
        FROM rooms AS room
        WHERE room.sector_id = sector.id
            AND room.deleted_at IS NULL
        ORDER BY
            CASE room.name
                WHEN 'Operacao' THEN 0
                WHEN 'Backoffice' THEN 1
                ELSE 2
            END,
            room.id
        LIMIT 1
    ),
    true,
    collaborator.is_active,
    'light',
    now() - INTERVAL '20 days' + (collaborator.sequence_number * INTERVAL '8 minutes'),
    now() - INTERVAL '20 days' + (collaborator.sequence_number * INTERVAL '8 minutes')
FROM ranked_collaborators AS collaborator
LEFT JOIN sectors AS sector
    ON sector.slug = collaborator.sector_slug
    AND sector.deleted_at IS NULL;

INSERT INTO user_sector_accesses (
    user_id,
    sector_id,
    access_level,
    created_at,
    updated_at
)
SELECT
    user_account.id,
    sector.id,
    CASE
        WHEN user_account.email IN ('admin@anadem.com.br', 'alisson.schimitz@aiatecnologia.com.br', 'adriel@anadem.org.br') THEN 'sector_admin'
        WHEN user_account.email = 'adilio.silva@aiatecnologia.com.br' THEN 'technician'
        ELSE 'requester'
    END,
    now(),
    now()
FROM demo_collaborators AS collaborator
JOIN users AS user_account
    ON user_account.email = collaborator.email
JOIN sectors AS sector
    ON sector.slug = collaborator.sector_slug
WHERE collaborator.sector_slug IS NOT NULL
    AND user_account.deleted_at IS NULL
    AND sector.deleted_at IS NULL;

INSERT INTO ticket_boards (
    sector_id,
    name,
    description,
    is_active,
    created_at,
    updated_at
)
SELECT
    sector.id,
    'Quadro ' || sector.name,
    'Quadro demo para o setor ' || sector.name || '.',
    true,
    now(),
    now()
FROM sectors AS sector
WHERE sector.deleted_at IS NULL;

INSERT INTO ticket_groups (
    ticket_board_id,
    name,
    slug,
    color,
    sort_order,
    is_collapsed_by_default,
    is_default,
    is_closed,
    is_active,
    created_at,
    updated_at
)
SELECT
    board.id,
    group_seed.name,
    group_seed.slug,
    group_seed.color,
    group_seed.sort_order,
    false,
    group_seed.is_default,
    group_seed.is_closed,
    true,
    now(),
    now()
FROM ticket_boards AS board
CROSS JOIN (
    VALUES
        ('Aberto', 'aberto', '#2563eb', 1, true, false),
        ('Em andamento', 'em-andamento', '#f59e0b', 2, false, false),
        ('Finalizado', 'finalizado', '#10b981', 3, false, true)
) AS group_seed(name, slug, color, sort_order, is_default, is_closed)
WHERE board.deleted_at IS NULL;

INSERT INTO ticket_statuses (
    ticket_board_id,
    name,
    slug,
    color,
    sort_order,
    is_closed,
    is_default,
    is_active,
    created_at,
    updated_at
)
SELECT
    board.id,
    status_seed.name,
    status_seed.slug,
    status_seed.color,
    status_seed.sort_order,
    status_seed.is_closed,
    status_seed.is_default,
    true,
    now(),
    now()
FROM ticket_boards AS board
CROSS JOIN (
    VALUES
        ('Novo', 'novo', '#2563eb', 1, false, true),
        ('Em atendimento', 'em-atendimento', '#f59e0b', 2, false, false),
        ('Resolvido', 'resolvido', '#10b981', 3, true, false)
) AS status_seed(name, slug, color, sort_order, is_closed, is_default)
WHERE board.deleted_at IS NULL;

INSERT INTO ticket_forms (
    ticket_board_id,
    name,
    description,
    is_default,
    is_active,
    created_at,
    updated_at
)
SELECT
    board.id,
    'Abertura padrao',
    'Formulario padrao para abertura de chamados do setor.',
    true,
    true,
    now(),
    now()
FROM ticket_boards AS board
WHERE board.deleted_at IS NULL;

INSERT INTO ticket_forms (
    ticket_board_id,
    name,
    description,
    is_default,
    is_active,
    created_at,
    updated_at
)
SELECT
    board.id,
    feature_seed.form_name,
    feature_seed.form_description,
    false,
    true,
    now(),
    now()
FROM ticket_boards AS board
JOIN sectors AS sector
    ON sector.id = board.sector_id
JOIN (
    VALUES
        ('ti', 'Incidente especializado', 'Formulario dedicado a incidentes e suporte tecnico.'),
        ('compras', 'Solicitacao de compra', 'Formulario dedicado a homologacao, cotacao e renovacao.'),
        ('financeiro', 'Analise financeira', 'Formulario dedicado a reembolso, conciliacao e ajustes.'),
        ('juridico', 'Demanda juridica', 'Formulario dedicado a revisoes contratuais e pareceres.')
) AS feature_seed(sector_slug, form_name, form_description)
    ON feature_seed.sector_slug = sector.slug
WHERE board.deleted_at IS NULL
    AND sector.deleted_at IS NULL;

INSERT INTO service_catalog_items (
    ticket_board_id,
    ticket_form_id,
    name,
    description,
    default_ticket_group_id,
    default_priority,
    is_active,
    created_at,
    updated_at
)
SELECT
    board.id,
    default_form.id,
    'Solicitacao geral',
    'Catalogo padrao para demandas gerais do setor.',
    default_group.id,
    'medium',
    true,
    now(),
    now()
FROM ticket_boards AS board
JOIN ticket_forms AS default_form
    ON default_form.ticket_board_id = board.id
    AND default_form.name = 'Abertura padrao'
    AND default_form.deleted_at IS NULL
JOIN ticket_groups AS default_group
    ON default_group.ticket_board_id = board.id
    AND default_group.slug = 'aberto'
    AND default_group.deleted_at IS NULL
WHERE board.deleted_at IS NULL;

INSERT INTO service_catalog_items (
    ticket_board_id,
    ticket_form_id,
    name,
    description,
    default_ticket_group_id,
    default_priority,
    is_active,
    created_at,
    updated_at
)
SELECT
    board.id,
    feature_form.id,
    feature_seed.catalog_name,
    feature_seed.catalog_description,
    default_group.id,
    feature_seed.default_priority,
    true,
    now(),
    now()
FROM ticket_boards AS board
JOIN sectors AS sector
    ON sector.id = board.sector_id
JOIN ticket_groups AS default_group
    ON default_group.ticket_board_id = board.id
    AND default_group.slug = 'aberto'
    AND default_group.deleted_at IS NULL
JOIN (
    VALUES
        ('ti', 'Incidente de TI', 'Fila prioritaria para falhas, acessos e infraestrutura.', 'high', 'Incidente especializado'),
        ('compras', 'Pedido de compra', 'Fila prioritaria para homologacao e aquisicoes.', 'medium', 'Solicitacao de compra'),
        ('financeiro', 'Analise financeira', 'Fila para reembolsos, centro de custo e fechamento.', 'medium', 'Analise financeira'),
        ('juridico', 'Demanda juridica', 'Fila para contratos, pareceres e conformidade.', 'high', 'Demanda juridica')
) AS feature_seed(sector_slug, catalog_name, catalog_description, default_priority, form_name)
    ON feature_seed.sector_slug = sector.slug
JOIN ticket_forms AS feature_form
    ON feature_form.ticket_board_id = board.id
    AND feature_form.name = feature_seed.form_name
    AND feature_form.deleted_at IS NULL
WHERE board.deleted_at IS NULL
    AND sector.deleted_at IS NULL;

INSERT INTO ticket_sla_policies (
    ticket_board_id,
    is_active,
    created_at,
    updated_at
)
SELECT
    board.id,
    true,
    now(),
    now()
FROM ticket_boards AS board
WHERE board.deleted_at IS NULL;

INSERT INTO ticket_sla_targets (
    ticket_sla_policy_id,
    priority,
    first_response_minutes,
    resolution_minutes,
    created_at,
    updated_at
)
SELECT
    policy.id,
    target_seed.priority,
    target_seed.first_response_minutes,
    target_seed.resolution_minutes,
    now(),
    now()
FROM ticket_sla_policies AS policy
CROSS JOIN (
    VALUES
        ('low', 240, 2880),
        ('medium', 120, 1440),
        ('high', 60, 480),
        ('urgent', 15, 240)
) AS target_seed(priority, first_response_minutes, resolution_minutes);

CREATE TEMP TABLE demo_sector_requesters ON COMMIT DROP AS
SELECT
    sector.slug AS sector_slug,
    user_account.id AS user_id,
    user_account.email AS email,
    ROW_NUMBER() OVER (
        PARTITION BY sector.id
        ORDER BY
            CASE user_sector_access.access_level
                WHEN 'requester' THEN 0
                WHEN 'technician' THEN 1
                WHEN 'sector_admin' THEN 2
                ELSE 3
            END,
            user_account.id
    ) AS ranking
FROM sectors AS sector
JOIN user_sector_accesses AS user_sector_access
    ON user_sector_access.sector_id = sector.id
JOIN users AS user_account
    ON user_account.id = user_sector_access.user_id
WHERE sector.deleted_at IS NULL
    AND user_account.deleted_at IS NULL
    AND user_account.is_active = true;

