CREATE TEMP TABLE demo_inserted_tickets ON COMMIT DROP AS
WITH priority_targets AS (
    SELECT 'low'::text AS priority, 240 AS first_response_minutes, 2880 AS resolution_minutes
    UNION ALL SELECT 'medium', 120, 1440
    UNION ALL SELECT 'high', 60, 480
    UNION ALL SELECT 'urgent', 15, 240
),
inserted AS (
    INSERT INTO tickets (
        sector_id,
        ticket_board_id,
        ticket_group_id,
        ticket_status_id,
        service_catalog_item_id,
        room_id,
        title,
        description,
        requester_id,
        assignee_id,
        priority,
        first_response_sla_minutes,
        first_response_due_at,
        first_responded_at,
        first_response_warning_sent_at,
        first_response_breached_at,
        resolution_sla_minutes,
        resolution_due_at,
        resolution_warning_sent_at,
        resolution_breached_at,
        resolved_at,
        last_activity_at,
        created_at,
        updated_at
    )
    SELECT
        sector.id,
        board.id,
        ticket_group.id,
        ticket_status.id,
        catalog_item.id,
        room.id,
        ticket_seed.title,
        ticket_seed.description,
        COALESCE(explicit_requester.id, default_requester.user_id, admin_user.id),
        assignee.id,
        ticket_seed.priority,
        target.first_response_minutes,
        ticket_seed.created_at + make_interval(mins => target.first_response_minutes),
        CASE ticket_seed.lifecycle
            WHEN 'open' THEN NULL
            WHEN 'in_progress' THEN ticket_seed.created_at + INTERVAL '35 minutes'
            WHEN 'closed' THEN ticket_seed.created_at + INTERVAL '20 minutes'
            ELSE NULL
        END,
        NULL,
        CASE
            WHEN ticket_seed.lifecycle = 'open'
                AND ticket_seed.priority IN ('high', 'urgent')
                AND ticket_seed.created_at < now() - INTERVAL '12 hours'
            THEN ticket_seed.created_at + make_interval(mins => target.first_response_minutes)
            ELSE NULL
        END,
        target.resolution_minutes,
        ticket_seed.created_at + make_interval(mins => target.resolution_minutes),
        CASE
            WHEN ticket_seed.lifecycle = 'in_progress'
                AND ticket_seed.priority IN ('high', 'urgent')
                AND ticket_seed.created_at < now() - INTERVAL '10 hours'
            THEN now() - INTERVAL '45 minutes'
            ELSE NULL
        END,
        CASE
            WHEN ticket_seed.lifecycle = 'open'
                AND ticket_seed.created_at < now() - INTERVAL '2 days'
            THEN ticket_seed.created_at + make_interval(mins => target.resolution_minutes)
            ELSE NULL
        END,
        CASE ticket_seed.lifecycle
            WHEN 'closed' THEN ticket_seed.created_at + INTERVAL '7 hours'
            ELSE NULL
        END,
        CASE ticket_seed.lifecycle
            WHEN 'open' THEN now() - INTERVAL '20 minutes'
            WHEN 'in_progress' THEN now() - INTERVAL '45 minutes'
            WHEN 'closed' THEN ticket_seed.created_at + INTERVAL '7 hours'
            ELSE ticket_seed.created_at
        END,
        ticket_seed.created_at,
        CASE ticket_seed.lifecycle
            WHEN 'closed' THEN ticket_seed.created_at + INTERVAL '7 hours'
            ELSE now()
        END
    FROM demo_ticket_seed AS ticket_seed
    JOIN sectors AS sector
        ON sector.slug = ticket_seed.sector_slug
        AND sector.deleted_at IS NULL
    JOIN ticket_boards AS board
        ON board.sector_id = sector.id
        AND board.deleted_at IS NULL
    JOIN ticket_groups AS ticket_group
        ON ticket_group.ticket_board_id = board.id
        AND ticket_group.slug = CASE ticket_seed.lifecycle
            WHEN 'closed' THEN 'finalizado'
            WHEN 'in_progress' THEN 'em-andamento'
            ELSE 'aberto'
        END
        AND ticket_group.deleted_at IS NULL
    JOIN ticket_statuses AS ticket_status
        ON ticket_status.ticket_board_id = board.id
        AND ticket_status.slug = CASE ticket_seed.lifecycle
            WHEN 'closed' THEN 'resolvido'
            WHEN 'in_progress' THEN 'em-atendimento'
            ELSE 'novo'
        END
        AND ticket_status.deleted_at IS NULL
    JOIN service_catalog_items AS catalog_item
        ON catalog_item.ticket_board_id = board.id
        AND catalog_item.name = ticket_seed.catalog_name
        AND catalog_item.deleted_at IS NULL
    LEFT JOIN rooms AS room
        ON room.sector_id = sector.id
        AND room.name = ticket_seed.room_name
        AND room.deleted_at IS NULL
    LEFT JOIN users AS explicit_requester
        ON explicit_requester.email = ticket_seed.requester_email
        AND explicit_requester.deleted_at IS NULL
        AND explicit_requester.is_active = true
    LEFT JOIN demo_sector_requesters AS default_requester
        ON default_requester.sector_slug = ticket_seed.sector_slug
        AND default_requester.ranking = 1
    LEFT JOIN users AS assignee
        ON assignee.email = ticket_seed.assignee_email
        AND assignee.deleted_at IS NULL
        AND assignee.is_active = true
    CROSS JOIN LATERAL (
        SELECT id
        FROM users
        WHERE email = 'admin@anadem.com.br'
        LIMIT 1
    ) AS admin_user
    JOIN priority_targets AS target
        ON target.priority = ticket_seed.priority
    RETURNING id, sector_id, requester_id, assignee_id, title, created_at, updated_at, resolved_at
)
SELECT * FROM inserted;

INSERT INTO ticket_messages (ticket_id, user_id, message, is_system, created_at, updated_at)
SELECT
    ticket_record.id,
    ticket_record.requester_id,
    'Registro inicial da solicitacao: ' || ticket_record.title || '.',
    false,
    ticket_record.created_at + INTERVAL '5 minutes',
    ticket_record.created_at + INTERVAL '5 minutes'
FROM demo_inserted_tickets AS ticket_record;

INSERT INTO ticket_messages (ticket_id, user_id, message, is_system, created_at, updated_at)
SELECT
    ticket_record.id,
    ticket_record.assignee_id,
    'Time operacional assumiu o acompanhamento e atualizou a proxima acao da fila.',
    false,
    ticket_record.created_at + INTERVAL '45 minutes',
    ticket_record.created_at + INTERVAL '45 minutes'
FROM demo_inserted_tickets AS ticket_record
WHERE ticket_record.assignee_id IS NOT NULL
    AND ticket_record.resolved_at IS NULL;

INSERT INTO ticket_messages (ticket_id, user_id, message, is_system, created_at, updated_at)
SELECT
    ticket_record.id,
    COALESCE(ticket_record.assignee_id, ticket_record.requester_id),
    'Chamado concluido na base de demonstracao com devolutiva registrada para o solicitante.',
    false,
    ticket_record.resolved_at,
    ticket_record.resolved_at
FROM demo_inserted_tickets AS ticket_record
WHERE ticket_record.resolved_at IS NOT NULL;

INSERT INTO notifications (id, type, notifiable_type, notifiable_id, data, read_at, created_at, updated_at)
SELECT
    pg_temp.demo_uuid('ticket-created:' || ticket_record.id || ':' || recipient.user_id),
    'App\\Modules\\Tickets\\Notifications\\TicketCreatedNotification',
    'App\\Models\\User',
    recipient.user_id,
    jsonb_build_object(
        'ticket_id', ticket_record.id,
        'title', 'Novo chamado na fila',
        'message', 'O chamado "' || ticket_record.title || '" foi criado para acompanhamento.',
        'url', '/tickets/' || ticket_record.id,
        'type', 'App\\Modules\\Tickets\\Notifications\\TicketCreatedNotification'
    )::text,
    CASE WHEN recipient.user_id = ticket_record.requester_id THEN ticket_record.created_at + INTERVAL '1 hour' ELSE NULL END,
    ticket_record.created_at + INTERVAL '10 minutes',
    ticket_record.created_at + INTERVAL '10 minutes'
FROM demo_inserted_tickets AS ticket_record
JOIN LATERAL (
    SELECT ticket_record.requester_id AS user_id
    UNION
    SELECT ticket_record.assignee_id AS user_id
) AS recipient
    ON recipient.user_id IS NOT NULL;

