CREATE TEMP TABLE demo_inserted_assets ON COMMIT DROP AS
WITH seeded_assets AS (
    SELECT
        asset_seed.*,
        ROW_NUMBER() OVER (ORDER BY asset_seed.sector_slug, asset_seed.name) AS sequence_number
    FROM demo_asset_seed AS asset_seed
),
inserted AS (
    INSERT INTO assets (
        uuid,
        asset_code,
        name,
        description,
        serial_number,
        brand,
        model,
        status,
        current_sector_id,
        current_room_id,
        current_user_id,
        created_by,
        created_at,
        updated_at
    )
    SELECT
        pg_temp.demo_uuid('asset:' || seeded_asset.sector_slug || ':' || seeded_asset.sequence_number || ':' || seeded_asset.name),
        'PAT-' || LPAD(seeded_asset.sequence_number::text, 6, '0'),
        seeded_asset.name,
        seeded_asset.description,
        seeded_asset.serial_number,
        seeded_asset.brand,
        seeded_asset.model,
        seeded_asset.status,
        sector.id,
        room.id,
        asset_user.id,
        creator.id,
        now() - seeded_asset.created_offset,
        now() - seeded_asset.created_offset
    FROM seeded_assets AS seeded_asset
    JOIN sectors AS sector
        ON sector.slug = seeded_asset.sector_slug
        AND sector.deleted_at IS NULL
    JOIN rooms AS room
        ON room.sector_id = sector.id
        AND room.name = seeded_asset.room_name
        AND room.deleted_at IS NULL
    LEFT JOIN users AS asset_user
        ON asset_user.email = seeded_asset.current_user_email
        AND asset_user.deleted_at IS NULL
    JOIN users AS creator
        ON creator.email = seeded_asset.created_by_email
        AND creator.deleted_at IS NULL
    RETURNING *
)
SELECT * FROM inserted;

