DO $$
DECLARE
    users_total integer;
    active_total integer;
    inactive_total integer;
    sectorless_total integer;
    sectors_total integer;
    boards_total integer;
    forms_total integer;
    catalog_total integer;
    tickets_total integer;
    knowledge_total integer;
    assets_total integer;
BEGIN
    SELECT COUNT(*) INTO users_total FROM users WHERE deleted_at IS NULL;
    SELECT COUNT(*) INTO active_total FROM users WHERE deleted_at IS NULL AND is_active = true;
    SELECT COUNT(*) INTO inactive_total FROM users WHERE deleted_at IS NULL AND is_active = false;
    SELECT COUNT(*) INTO sectorless_total FROM users WHERE deleted_at IS NULL AND sector_id IS NULL;
    SELECT COUNT(*) INTO sectors_total FROM sectors WHERE deleted_at IS NULL;
    SELECT COUNT(*) INTO boards_total FROM ticket_boards WHERE deleted_at IS NULL;
    SELECT COUNT(*) INTO forms_total FROM ticket_forms WHERE deleted_at IS NULL AND is_active = true;
    SELECT COUNT(*) INTO catalog_total FROM service_catalog_items WHERE deleted_at IS NULL AND is_active = true;
    SELECT COUNT(*) INTO tickets_total FROM tickets WHERE deleted_at IS NULL;
    SELECT COUNT(*) INTO knowledge_total FROM knowledge_base_articles WHERE deleted_at IS NULL AND is_active = true;
    SELECT COUNT(*) INTO assets_total FROM assets;

    IF users_total <> 174 THEN
        RAISE EXCEPTION 'Quantidade de usuarios diferente do esperado. Atual: %, esperado: %.', users_total, 174;
    END IF;

    IF active_total <> 169 THEN
        RAISE EXCEPTION 'Quantidade de usuarios ativos diferente do esperado. Atual: %, esperado: %.', active_total, 169;
    END IF;

    IF inactive_total <> 5 THEN
        RAISE EXCEPTION 'Quantidade de usuarios inativos diferente do esperado. Atual: %, esperado: %.', inactive_total, 5;
    END IF;

    IF sectorless_total <> 70 THEN
        RAISE EXCEPTION 'Quantidade de usuarios sem setor diferente do esperado. Atual: %, esperado: %.', sectorless_total, 70;
    END IF;

    IF sectors_total <> 18 THEN
        RAISE EXCEPTION 'Quantidade de setores diferente do esperado. Atual: %, esperado: %.', sectors_total, 18;
    END IF;

    IF boards_total <> 18 THEN
        RAISE EXCEPTION 'Cada setor deveria ter um quadro ativo. Atual: %, esperado: %.', boards_total, 18;
    END IF;

    IF forms_total < 18 THEN
        RAISE EXCEPTION 'Quantidade de formularios insuficiente. Atual: %, minimo esperado: %.', forms_total, 18;
    END IF;

    IF catalog_total < 18 THEN
        RAISE EXCEPTION 'Quantidade de itens de catalogo insuficiente. Atual: %, minimo esperado: %.', catalog_total, 18;
    END IF;

    IF tickets_total < 18 THEN
        RAISE EXCEPTION 'Quantidade de tickets insuficiente. Atual: %, minimo esperado: %.', tickets_total, 18;
    END IF;

    IF knowledge_total < 8 THEN
        RAISE EXCEPTION 'Quantidade de artigos insuficiente. Atual: %, minimo esperado: 8.', knowledge_total;
    END IF;

    IF assets_total < 8 THEN
        RAISE EXCEPTION 'Quantidade de ativos insuficiente. Atual: %, minimo esperado: 8.', assets_total;
    END IF;
END $$;

COMMIT;

SELECT
    (SELECT COUNT(*) FROM companies WHERE deleted_at IS NULL) AS companies,
    (SELECT COUNT(*) FROM sectors WHERE deleted_at IS NULL) AS sectors,
    (SELECT COUNT(*) FROM rooms WHERE deleted_at IS NULL) AS rooms,
    (SELECT COUNT(*) FROM users WHERE deleted_at IS NULL) AS users_total,
    (SELECT COUNT(*) FROM users WHERE deleted_at IS NULL AND is_active = true) AS users_active,
    (SELECT COUNT(*) FROM users WHERE deleted_at IS NULL AND is_active = false) AS users_inactive,
    (SELECT COUNT(*) FROM users WHERE deleted_at IS NULL AND sector_id IS NULL) AS users_without_sector,
    (SELECT COUNT(*) FROM ticket_boards WHERE deleted_at IS NULL) AS boards,
    (SELECT COUNT(*) FROM ticket_forms WHERE deleted_at IS NULL) AS forms,
    (SELECT COUNT(*) FROM service_catalog_items WHERE deleted_at IS NULL) AS catalog_items,
    (SELECT COUNT(*) FROM tickets WHERE deleted_at IS NULL) AS tickets,
    (SELECT COUNT(*) FROM ticket_messages) AS ticket_messages,
    (SELECT COUNT(*) FROM notifications) AS notifications,
    (SELECT COUNT(*) FROM knowledge_base_articles WHERE deleted_at IS NULL) AS knowledge_articles,
    (SELECT COUNT(*) FROM assets) AS assets,
    (SELECT COUNT(*) FROM asset_movements) AS asset_movements;
